-- W34 — Assistant: chat interaction audit log + edital→n8n RAG sync queue (REQ-7.x).
-- Next free number after 21_w33_hub_faq_lgpd.sql.

CREATE TABLE IF NOT EXISTS "AssistantInteracoes" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "session_id" VARCHAR(64) NOT NULL,
  "id_usuario" BIGINT NULL,
  "page_id" VARCHAR(255) NULL,
  "chat_input" TEXT NOT NULL,
  "audio_flag" BOOLEAN NOT NULL DEFAULT FALSE,
  "resposta_agente" TEXT NULL,
  "arquivos_usados" JSON NULL,
  "sentimento" VARCHAR(32) NULL,
  "thumbs" VARCHAR(8) NULL,
  "criado_em" TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT "chk_assistant_interacoes_thumbs"
    CHECK ("thumbs" IN ('up', 'down'))
);

CREATE TABLE IF NOT EXISTS "AssistantIngestoes" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_edital" BIGINT NOT NULL,
  "operacao" VARCHAR(16) NOT NULL,
  "status" VARCHAR(16) NOT NULL DEFAULT 'pendente',
  "erro" TEXT NULL,
  "enviado_em" TIMESTAMP NULL,
  "criado_em" TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT "chk_assistant_ingestoes_operacao"
    CHECK ("operacao" IN ('insert', 'update', 'delete')),
  CONSTRAINT "chk_assistant_ingestoes_status"
    CHECK ("status" IN ('pendente', 'enviado', 'erro'))
);

CREATE INDEX "idx_assistant_ingestoes_status"
  ON "AssistantIngestoes"("status");

COMMENT ON TABLE "AssistantInteracoes" IS
  'W34 audit log of chat interactions with the assistant. id_usuario NULL for anonymous users.';
COMMENT ON COLUMN "AssistantInteracoes"."session_id" IS
  'Client chat session identifier (UUID).';
COMMENT ON COLUMN "AssistantInteracoes"."id_usuario" IS
  'Usuarios.id when authenticated; NULL for anonymous users. Soft ref, no hard FK.';
COMMENT ON COLUMN "AssistantInteracoes"."page_id" IS
  'PWA page/route where the chat was opened (e.g. edital detail).';
COMMENT ON COLUMN "AssistantInteracoes"."chat_input" IS
  'Raw user message sent to the assistant.';
COMMENT ON COLUMN "AssistantInteracoes"."audio_flag" IS
  'TRUE when the message was captured via voice input.';
COMMENT ON COLUMN "AssistantInteracoes"."resposta_agente" IS
  'Assistant answer returned by n8n. NULL when the interaction failed.';
COMMENT ON COLUMN "AssistantInteracoes"."arquivos_usados" IS
  'JSON array of sources/files used to answer (edital PDFs, docs).';
COMMENT ON COLUMN "AssistantInteracoes"."sentimento" IS
  'Sentiment computed by n8n: positivo|neutro|negativo.';
COMMENT ON COLUMN "AssistantInteracoes"."thumbs" IS
  'User feedback: up|down, NULL when not rated.';
COMMENT ON COLUMN "AssistantInteracoes"."criado_em" IS
  'When the interaction was logged.';

COMMENT ON TABLE "AssistantIngestoes" IS
  'W34 deferred queue of edital changes to sync into the n8n RAG index.';
COMMENT ON COLUMN "AssistantIngestoes"."id_edital" IS
  'Editais.id to (re)ingest. Soft ref, no hard FK (payload is edital metadata; n8n fetches the PDF from termos_valor).';
COMMENT ON COLUMN "AssistantIngestoes"."operacao" IS
  'insert|update|delete — change to apply to the RAG index.';
COMMENT ON COLUMN "AssistantIngestoes"."status" IS
  'pendente|enviado|erro — flush query reads WHERE status = ''pendente''.';
COMMENT ON COLUMN "AssistantIngestoes"."erro" IS
  'Error detail when status = erro.';
COMMENT ON COLUMN "AssistantIngestoes"."enviado_em" IS
  'When the row was flushed to n8n. NULL while pendente.';
COMMENT ON COLUMN "AssistantIngestoes"."criado_em" IS
  'When the queue entry was created.';